// TestQAEpisodeTitlesJoint — episode-titles g3 box 3.1, the Tier-1 joint over
// the qa_shikimori_joint pattern: REAL store, REAL queue (the real FetchGate),
// the serial seed registry, and the shikimori plugin SUBPROCESS over a stub
// upstream serving the anchored plan's THREE endpoints — /api/animes/{id},
// /api/animes/{id}/roles AND /api/animes/{id}/episodes. shikimori.io stands in
// NEVER; the transport swap is the one injection the black-box joint allows
// (restored on cleanup, and no test in this package runs parallel).
//
// The scenario walks the plugin → core refresh → episode-documents contract
// end to end, no mocks of the units under test:
//
//  1. a serial library scans; the series row drains its organic SEARCH leg
//     (one fetch — search plans declare no extras, so nothing is routed yet);
//  2. the sweep strips the series row and its re-drain runs ANCHORED — by-id
//     + roles + EPISODES (UA and the 700 ms gate asserted on every recorded
//     request) — and Convert's EpisodeTitles entries are ROUTED onto the
//     episode documents: season + number matched against the series' own
//     season, stamps over the run's hints and match confidence, and the
//     served episode block (GET /series/{id}/episodes, the element surface)
//     names shikimori; an episode of ANOTHER season in the same directory
//     stays untouched;
//  3. PUT /series/{id}/identify with the OTHER anime id synchronously strips
//     the series AND its routed episode titles (the scopeWithEpisodes
//     cascade — stripped counts series + the two routed episodes, the
//     never-routed other-season episode counts nothing) and re-anchors the
//     row; the checkpoint right after the 202 is deterministic because the
//     re-landing run needs three MORE gate-paced fetches;
//  4. the fresh anchored run rewrites the routed titles from the picked
//     anime's episodes payload and the series namespace carries the picked
//     facts — the tail of the recording proves the anchor drove it (exactly
//     the picked id's three by-id endpoints, never a search).
package itest

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"net/url"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/enrich"
	"github.com/mellifera/mellifera/pkg/sdk"
)

// Fixture identity constants (no-coincidence discipline: independent of the
// plugin suites' AND the other joints' fixtures) and the request-plan path
// shapes re-derived from the plugin's shipped templates.
const (
	qaEpDir   = "Space Odyssey S01"
	qaEpTitle = "Space Odyssey" // the shared grammar's season cut of the dir
	qaEpIDa   = 4301            // the organic search's anime (anchor source)
	qaEpIDb   = 4302            // the identify pick — absent from every search list

	qaEpRelE1 = qaEpDir + "/Space Odyssey S01E01.mkv" // season 1 episode 1 — routed
	qaEpRelE2 = qaEpDir + "/Space Odyssey S01E02.mkv" // season 1 episode 2 — routed
	qaEpRelS2 = qaEpDir + "/Space Odyssey S02E01.mkv" // season 2 episode 1 — the honest guard
)

// qaEpTitlesA / qaEpTitlesB are the two episodes payloads' russian names
// (the RU-first decode the plugin prefers) projected per episode number.
var (
	qaEpTitlesA = map[int]string{1: "Эпизод первый", 2: "Часть вторая"}
	qaEpTitlesB = map[int]string{1: "Ремастер первый", 2: "Ремастер вторая"}

	// qaEpWantA/B are the two anime fixtures projected into the series
	// namespace expectation (the shared shikimori-joint want shape).
	qaEpWantA = qaShikWant{id: qaEpIDa, episodes: 26, romaji: "Space Odyssey", russian: "Космическая Одиссея", aired: "1968-04-02", score: 8.1}
	qaEpWantB = qaShikWant{id: qaEpIDb, episodes: 13, romaji: "Space Odyssey Remastered", russian: "Космическая Одиссея Ремастер", aired: "2001-09-01", score: 7.7}
)

// qaEpAnime builds one upstream anime payload via the shared builder (the v1
// shape Convert decodes; score is a decimal STRING upstream).
func qaEpAnime(id int, name, russian string, episodes int, aired, score string) map[string]any {
	return qaShikAnime(id, name, russian, "tv", episodes, aired, score)
}

// qaEpRoles builds one roles payload (extras[0]; the convention cast — served
// so the anchored plan's first extra decodes, though the cast is not this
// box's assertion).
func qaEpRoles(character, russianCharacter, seiyuu string) []map[string]any {
	return []map[string]any{{
		"name": character, "russian": russianCharacter,
		"image": map[string]any{"original": "/images/characters/" + strconv.Itoa(len(character)) + ".jpg"},
		"seyu":  []map[string]any{{"name": seiyuu, "russian": seiyuu + " (рус)"}},
	}}
}

// qaEpEpisodes builds one episodes payload (extras[1]; the per-episode title
// source — russian preferred, name the fallback).
func qaEpEpisodes(titles map[int]string, nameOf map[int]string) []map[string]any {
	out := make([]map[string]any, 0, len(titles))
	for ep := 1; ep <= len(titles); ep++ {
		out = append(out, map[string]any{
			"episode": ep, "name": nameOf[ep], "russian": titles[ep],
		})
	}
	return out
}

// qaEpStub is the fake upstream: it records every request and serves the
// search lists, the by-id anime payloads, and the anchored plan's two extra
// endpoints (roles + episodes) per anime id.
type qaEpStub struct {
	srv      *httptest.Server
	mu       sync.Mutex
	seen     []qaShikReq
	search   map[string][]map[string]any
	anime    map[int]map[string]any
	roles    map[int][]map[string]any
	episodes map[int][]map[string]any
}

// qaEpStartStub builds the fixture maps and starts the stub server. Anime B
// is served under its by-id endpoints ONLY (never in a search list) — the
// identify pick's anchored re-derive is what makes its facts land.
func qaEpStartStub(t *testing.T) *qaEpStub {
	t.Helper()
	s := &qaEpStub{
		search: map[string][]map[string]any{
			qaEpTitle: {qaEpAnime(qaEpIDa, qaEpWantA.romaji, qaEpWantA.russian, qaEpWantA.episodes, qaEpWantA.aired, "8.1")},
		},
		anime: map[int]map[string]any{
			qaEpIDa: qaEpAnime(qaEpIDa, qaEpWantA.romaji, qaEpWantA.russian, qaEpWantA.episodes, qaEpWantA.aired, "8.1"),
			qaEpIDb: qaEpAnime(qaEpIDb, qaEpWantB.romaji, qaEpWantB.russian, qaEpWantB.episodes, qaEpWantB.aired, "7.7"),
		},
		roles: map[int][]map[string]any{
			qaEpIDa: qaEpRoles("HAL 9000", "Хол 9000", "Douglas Rain"),
			qaEpIDb: qaEpRoles("HAL 9000 MK2", "Хол 9000 МК2", "Douglas Rain II"),
		},
		episodes: map[int][]map[string]any{
			qaEpIDa: qaEpEpisodes(qaEpTitlesA, map[int]string{1: "Episode One", 2: "Part Two"}),
			qaEpIDb: qaEpEpisodes(qaEpTitlesB, map[int]string{1: "Remastered One", 2: "Remastered Two"}),
		},
	}
	mux := http.NewServeMux()
	mux.HandleFunc(qaShikAPI, func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		list, ok := s.search[r.URL.Query().Get("search")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		qaShikWriteJSON(t, w, list)
	})
	mux.HandleFunc(qaShikAPI+"/", func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		id, sub, keyed := strings.Cut(strings.TrimPrefix(r.URL.Path, qaShikAPI+"/"), "/")
		n, err := strconv.Atoi(id)
		if !keyed { // the by-id single-object fetch
			if err != nil {
				http.NotFound(w, r)
				return
			}
			anime, ok := s.anime[n]
			if !ok {
				http.NotFound(w, r)
				return
			}
			qaShikWriteJSON(t, w, anime)
			return
		}
		switch sub {
		case "roles":
			list, ok := s.roles[n]
			if !ok {
				http.NotFound(w, r)
				return
			}
			qaShikWriteJSON(t, w, list)
		case "episodes":
			list, ok := s.episodes[n]
			if !ok {
				http.NotFound(w, r)
				return
			}
			qaShikWriteJSON(t, w, list)
		default:
			http.NotFound(w, r)
		}
	})
	s.srv = httptest.NewServer(mux)
	t.Cleanup(s.srv.Close)
	return s
}

func (s *qaEpStub) record(r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.seen = append(s.seen, qaShikReq{
		method: r.Method, path: r.URL.Path, query: r.URL.RawQuery,
		ua: r.Header.Get("User-Agent"), at: time.Now(),
	})
}

func (s *qaEpStub) requests() []qaShikReq {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]qaShikReq(nil), s.seen...)
}

// qaEpJoint is one composed joint round trip.
type qaEpJoint struct {
	w    *pbWorld
	q    *enrich.Queue
	stub *qaEpStub
	lib  int64
}

// qaEpStartJoint composes the joint: the pbWorld graph + the three metadata
// plugin subprocesses + the real queue (the real FetchGate — the
// cmd/mellifera wiring shape, never nil) + the scan Notify hook (the main.go
// scanDeps.Notify shape, mirrored in miniature per the harness contract),
// then lays the media and creates the serial library.
func qaEpStartJoint(t *testing.T) *qaEpJoint {
	t.Helper()
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skipf("episode-titles joint needs ffmpeg on PATH (episode fixtures are lavfi-generated): %v", err)
	}
	w := pbNewWorld(t)
	tmp := t.TempDir()
	metaCaps := []sdk.Capability{{Type: "metadata_source", ID: "default", ProtoService: "mellifera.metadata.v1.MetadataSource"}}
	paths := map[string]string{
		"serial-parser": buildBinary(t, tmp, "qa-ep-serial-parser", "./plugins/serial-parser"),
		"frame-grabber": buildBinary(t, tmp, "qa-ep-frame-grabber", "./plugins/frame-grabber"),
		"shikimori":     buildBinary(t, tmp, "qa-ep-shikimori", "./plugins/shikimori"),
	}
	for id, path := range paths {
		if err := w.mgr.Load(id, path, metaCaps); err != nil {
			t.Fatalf("load %s: %v", id, err)
		}
		if err := w.mgr.Start(context.Background(), id); err != nil {
			t.Fatalf("start %s: %v", id, err)
		}
	}
	t.Cleanup(func() {
		stopCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		for id := range paths {
			_ = w.mgr.Stop(stopCtx, id)
		}
	})

	j := &qaEpJoint{w: w, stub: qaEpStartStub(t)}
	deps := enrich.Deps{Store: w.st, Modules: w.reg, Plugins: w.mgr, FetchGate: enrich.NewFetchGate()}
	j.q = enrich.NewQueue(deps, enrich.QueueConfig{Workers: 2, Backoff: 10 * time.Millisecond})
	if err := j.q.Start(context.Background()); err != nil {
		t.Fatalf("queue start: %v", err)
	}
	t.Cleanup(j.q.Stop)
	// The scan Notify hook — main.go's shape, INCLUDING its context rule
	// (main.go INV-context-shared).
	w.scanDep.Notify = func(ctx context.Context, libraryID int64) {
		j.q.Notify(context.WithoutCancel(ctx), libraryID)
	}

	// The stub host swap: no test in this package sets t.Parallel, and the
	// cleanup restores before any later test in the binary runs.
	saved := http.DefaultTransport
	stubURL, err := url.Parse(j.stub.srv.URL)
	if err != nil {
		t.Fatalf("parse stub url: %v", err)
	}
	http.DefaultTransport = &qaShikRewrite{stub: stubURL, next: saved}
	t.Cleanup(func() { http.DefaultTransport = saved })

	root := t.TempDir()
	for _, rel := range []string{qaEpRelE1, qaEpRelE2, qaEpRelS2} {
		qaSerialMedia(t, filepath.Join(root, rel))
	}
	j.lib = qaSerialCreateLibrary(t, w.client, w.baseURL, w.token, root, "QA Episode Titles Joint")
	return j
}

// TestQAEpisodeTitlesJoint is the episode-titles Tier-1 joint: the plugin's
// anchored episodes fetch, the core's routing onto episode documents, the
// identify strip cascade, and the fresh rewrite — over the real graph.
func TestQAEpisodeTitlesJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("episode-titles joint: skips under -short (builds binaries + subprocesses)")
	}
	j := qaEpStartJoint(t)
	ctx := context.Background()

	// --- leg 1: the organic scan-drain — the SEARCH leg anchors the series ---
	scanRes := pbScanLibrary(t, j.w, j.lib)
	if scanRes.Persisted != 4 { // 1 series row + 3 episode rows
		t.Fatalf("scan persisted %d rows, want 4 (1 series + 3 episodes); warnings=%v", scanRes.Persisted, scanRes.Warnings)
	}
	seriesA := qaEpAwaitSeries(t, j)
	qaEpAssertSeriesNamespace(t, j, seriesA, qaEpWantA)

	// The search leg's upstream contract: exactly ONE fetch, on the search
	// endpoint, for the derived title — a search plan declares NO extras, so
	// no episodes payload has run and nothing can be routed yet.
	reqs := j.stub.requests()
	if len(reqs) != 1 {
		t.Fatalf("leg 1: upstream saw %d requests, want 1 search fetch: %+v", len(reqs), reqs)
	}
	qaEpAssertAllRequests(t, reqs)
	qaEpAssertTailPaths(t, reqs, qaShikAPI)
	q, err := url.ParseQuery(reqs[0].query)
	if err != nil {
		t.Fatalf("leg 1: bad search query %q: %v", reqs[0].query, err)
	}
	if q.Get("search") != qaEpTitle || q.Get("limit") == "" {
		t.Errorf("leg 1: search query = %q, want search=%q with a bounded page size", reqs[0].query, qaEpTitle)
	}

	// Pre-anchor honesty: wait for every episode row to settle (an episode's
	// chain carries a real ffmpeg exec — episodes settle after the series
	// row), then pin the served episode block (the element surface) carrying
	// NO shikimori namespace yet — on every episode, including the
	// other-season one.
	eps := qaEpAwaitSettled(t, j, seriesA)
	qaEpAssertUntouchedEpisode(t, qaEpRelE1, eps[qaEpRelE1], 1, 1)
	qaEpAssertUntouchedEpisode(t, qaEpRelE2, eps[qaEpRelE2], 1, 2)
	qaEpAssertUntouchedEpisode(t, qaEpRelS2, eps[qaEpRelS2], 2, 1)

	// --- leg 2: the sweep strips the series row; its re-drain runs ANCHORED
	// (by-id + roles + EPISODES) and the entries route onto the episode docs ---
	stripped, deferred, err := j.q.ReenrichSource(ctx, j.lib, "shikimori")
	if err != nil {
		t.Fatalf("ReenrichSource: %v", err)
	}
	if stripped != 1 || deferred != 0 {
		t.Fatalf("sweep = stripped %d deferred %d, want 1/0 (only the series carries the namespace pre-routing)", stripped, deferred)
	}
	eps = qaEpAwaitRouted(t, j, seriesA, map[string]string{
		qaEpRelE1: qaEpTitlesA[1], qaEpRelE2: qaEpTitlesA[2],
	})
	qaEpAssertRoutedEpisode(t, qaEpRelE1, eps[qaEpRelE1], qaEpTitlesA[1], 1, 1, qaEpWantA.id)
	qaEpAssertRoutedEpisode(t, qaEpRelE2, eps[qaEpRelE2], qaEpTitlesA[2], 1, 2, qaEpWantA.id)
	// The season guard: another season's episode in the SAME directory stays
	// titleless instead of wrong.
	qaEpAssertUntouchedEpisode(t, qaEpRelS2, eps[qaEpRelS2], 2, 1)
	// The series row itself re-derived anchored onto the SAME identity (the
	// run doc is committed BEFORE routing runs — the episode titles landing
	// proves the run document is already durable).
	qaEpAssertSeriesNamespace(t, j, seriesA, qaEpWantA)

	// The anchored leg's upstream contract: the tail is EXACTLY anime A's
	// three request-plan endpoints (by-id, roles, episodes) — the anchor
	// drove the run, and the episodes extra rode it second.
	reqs = j.stub.requests()
	if len(reqs) != 4 { // 1 search + 3 anchored
		t.Fatalf("leg 2: upstream saw %d requests, want 4: %+v", len(reqs), reqs)
	}
	qaEpAssertAllRequests(t, reqs)
	qaEpAssertTailPaths(t, reqs[1:], qaShikAPI+"/"+strconv.Itoa(qaEpIDa),
		qaShikAPI+"/"+strconv.Itoa(qaEpIDa)+"/roles",
		qaShikAPI+"/"+strconv.Itoa(qaEpIDa)+"/episodes")

	// --- the identify PUT: cascade strip + re-anchor to the OTHER anime ---
	shim := api.New(api.Deps{
		AdminToken: j.w.token,
		Store:      j.w.st,
		IdentifySeries: func(ctx context.Context, seriesID, pluginID, externalID string) (bool, int, int, error) {
			return j.q.IdentifySeries(context.WithoutCancel(ctx), seriesID, pluginID, externalID)
		},
	})
	identifySrv := httptest.NewServer(shim)
	t.Cleanup(identifySrv.Close)

	var result struct {
		Queued   bool `json:"queued"`
		Stripped int  `json:"stripped"`
		Deferred int  `json:"deferred"`
	}
	pick := map[string]string{"source_id": "shikimori", "external_id": strconv.Itoa(qaEpIDb)}
	if status := doRequest(t, j.w.client, http.MethodPut,
		identifySrv.URL+"/api/v1/series/"+seriesA+"/identify", j.w.token, pick, &result); status != http.StatusAccepted {
		t.Fatalf("identify PUT: HTTP %d, want 202", status)
	}
	// THE CASCADE: stripped counts the series AND its two routed episode
	// titles; the scoped-but-never-routed other-season episode counts nothing.
	if !result.Queued || result.Stripped != 3 || result.Deferred != 0 {
		t.Fatalf("identify PUT = %+v, want queued=true stripped=3 (series + 2 routed episodes) deferred=0", result)
	}

	// The post-strip checkpoint is DETERMINISTIC, not a sleep: the PUT
	// returns only after the synchronous strip, and the re-landing run needs
	// three MORE gate-paced fetches (>= 700 ms apart) before any namespace —
	// run doc or routed title — can exist again. Right now: the strip purged
	// shikimori's namespace/_provenance/_view from the series AND both routed
	// episodes, the other-season episode is untouched, and the anchor already
	// names the picked anime.
	eps = qaEpServedEpisodes(t, j, seriesA)
	qaEpAssertStrippedEpisode(t, qaEpRelE1, eps[qaEpRelE1], 1, 1)
	qaEpAssertStrippedEpisode(t, qaEpRelE2, eps[qaEpRelE2], 1, 2)
	qaEpAssertUntouchedEpisode(t, qaEpRelS2, eps[qaEpRelS2], 2, 1)
	qaEpAssertStrippedSeries(t, j, seriesA, qaEpIDb)

	// --- leg 3: the fresh anchored run rewrites the routed titles from the
	// picked anime's episodes payload ---
	eps = qaEpAwaitRouted(t, j, seriesA, map[string]string{
		qaEpRelE1: qaEpTitlesB[1], qaEpRelE2: qaEpTitlesB[2],
	})
	qaEpAssertRoutedEpisode(t, qaEpRelE1, eps[qaEpRelE1], qaEpTitlesB[1], 1, 1, qaEpWantB.id)
	qaEpAssertRoutedEpisode(t, qaEpRelE2, eps[qaEpRelE2], qaEpTitlesB[2], 1, 2, qaEpWantB.id)
	qaEpAssertUntouchedEpisode(t, qaEpRelS2, eps[qaEpRelS2], 2, 1)
	qaEpAssertSeriesNamespace(t, j, seriesA, qaEpWantB)

	// The fresh leg's upstream contract: the whole recording is exactly
	// search + A's plan + B's plan — the anchor drove the rewrite (a search
	// request here would break the total or the tail's paths; B is in NO
	// search list, so a search fallback could never land its facts).
	reqs = j.stub.requests()
	if len(reqs) != 7 { // 1 search + 3 + 3
		t.Fatalf("leg 3: upstream saw %d requests, want 7: %+v", len(reqs), reqs)
	}
	qaEpAssertAllRequests(t, reqs)
	qaEpAssertTailPaths(t, reqs[4:], qaShikAPI+"/"+strconv.Itoa(qaEpIDb),
		qaShikAPI+"/"+strconv.Itoa(qaEpIDb)+"/roles",
		qaShikAPI+"/"+strconv.Itoa(qaEpIDb)+"/episodes")
}

// qaEpAwaitSeries polls the library's series rows until the fixture dir's row
// settles ready with its shikimori namespace landed, returning the series id.
func qaEpAwaitSeries(t *testing.T, j *qaEpJoint) string {
	t.Helper()
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for time.Now().Before(deadline) {
		for _, sr := range qaSerialListSeries(t, j.w.client, j.w.baseURL, j.w.token, j.lib) {
			if sr.RelativePath == qaEpDir && sr.Status == "ready" && parseAsyncDoc(t, sr.Document).Sources["shikimori"] != nil {
				return sr.ID
			}
		}
		time.Sleep(probeInterval)
	}
	for _, sr := range qaSerialListSeries(t, j.w.client, j.w.baseURL, j.w.token, j.lib) {
		if sr.RelativePath == qaEpDir {
			t.Fatalf("series %q: shikimori namespace never landed (status %s); queue stats %+v; doc:\n%s",
				qaEpDir, sr.Status, j.q.Stats(), sr.Document)
		}
	}
	t.Fatalf("series %q missing from library %d", qaEpDir, j.lib)
	return ""
}

// qaEpAwaitSettled polls the served episode block until all three episode
// rows have settled ready with their parse namespaces landed — the state the
// pre-anchor assertions need to be timing-free.
func qaEpAwaitSettled(t *testing.T, j *qaEpJoint, seriesID string) map[string]itemDTO {
	t.Helper()
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for time.Now().Before(deadline) {
		eps := qaEpServedEpisodes(t, j, seriesID)
		if len(eps) == 3 {
			settled := true
			for _, it := range eps {
				if it.Status != "ready" || parseAsyncDoc(t, it.Document).Sources["serial-parser"] == nil {
					settled = false
					break
				}
			}
			if settled {
				return eps
			}
		}
		time.Sleep(probeInterval)
	}
	for rel, it := range qaEpServedEpisodes(t, j, seriesID) {
		t.Fatalf("episodes never settled: %q status %s doc:\n%s", rel, it.Status, it.Document)
	}
	return nil
}

// qaEpServedEpisodes fetches the served episode block — GET /series/{id}/
// episodes over the real api+web surface — and indexes it by relative path.
func qaEpServedEpisodes(t *testing.T, j *qaEpJoint, seriesID string) map[string]itemDTO {
	t.Helper()
	var resp itemsResponse
	status := doRequest(t, j.w.client, http.MethodGet,
		j.w.baseURL+"/api/v1/series/"+seriesID+"/episodes", j.w.token, nil, &resp)
	if status != http.StatusOK {
		t.Fatalf("GET /series/%s/episodes: HTTP %d, want 200", seriesID, status)
	}
	return indexByPath(t, resp.Items)
}

// qaEpAwaitRouted polls the served episode block until every rel in want
// carries its routed shikimori title, returning the block for the full
// assertions. The failure dump carries every episode's raw document.
func qaEpAwaitRouted(t *testing.T, j *qaEpJoint, seriesID string, want map[string]string) map[string]itemDTO {
	t.Helper()
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for time.Now().Before(deadline) {
		eps := qaEpServedEpisodes(t, j, seriesID)
		landed := true
		for rel, title := range want {
			it, ok := eps[rel]
			if !ok {
				t.Fatalf("served episode block lost %q (have %v)", rel, pathsOf(eps))
			}
			doc := parseAsyncDoc(t, it.Document)
			ns := doc.Sources["shikimori"]
			if ns == nil || ns["title"] != title {
				landed = false
				break
			}
		}
		if landed {
			return eps
		}
		time.Sleep(probeInterval)
	}
	eps := qaEpServedEpisodes(t, j, seriesID)
	for rel, it := range eps {
		t.Fatalf("routed titles never landed: %q status %s doc:\n%s", rel, it.Status, it.Document)
	}
	return nil
}

// qaEpAssertRoutedEpisode pins one routed episode document: the routed
// namespace is the episode title entry; the stamps name shikimori over the
// run's inputs (the ANCHORED match confidence, the upstream source url); the
// parser facts the match read are intact underneath.
func qaEpAssertRoutedEpisode(t *testing.T, rel string, it itemDTO, title string, season, episode, animeID int) {
	t.Helper()
	doc := parseAsyncDoc(t, it.Document)
	ns := doc.Sources["shikimori"]
	if ns == nil {
		t.Fatalf("%q: sources.shikimori missing (want the routed title %q); doc:\n%s", rel, title, it.Document)
	}
	if ns["title"] != title {
		t.Errorf("%q: sources.shikimori.title = %v, want %q (the routed episode entry)", rel, ns["title"], title)
	}
	qaEpAssertParserFacts(t, rel, doc, season, episode)

	prov, ok := doc.Provenance["title"]
	if !ok {
		t.Fatalf("%q: _provenance.title missing (the routed stamps must ride the write); doc:\n%s", rel, it.Document)
	}
	if asyncStr(prov, "plugin_id") != "shikimori" {
		t.Errorf("%q: _provenance.title.plugin_id = %v, want shikimori", rel, prov["plugin_id"])
	}
	if c, _ := prov["confidence"].(float64); c != 1.0 {
		t.Errorf("%q: _provenance.title.confidence = %v, want 1.0 (the anchored match confidence the run carried)", rel, prov["confidence"])
	}
	if wantURL := "https://" + qaShikHost + qaShikAPI + "/" + strconv.Itoa(animeID) + "-qa"; asyncStr(prov, "source_url") != wantURL {
		t.Errorf("%q: _provenance.title.source_url = %q, want the picked anime's upstream url %q", rel, prov["source_url"], wantURL)
	}
	if asyncStr(prov, "plugin_version") == "" {
		t.Errorf("%q: _provenance.title.plugin_version empty (the run's hint must ride the stamp)", rel)
	}

	view, ok := doc.View["title"]
	if !ok {
		t.Fatalf("%q: _view.title missing; doc:\n%s", rel, it.Document)
	}
	if asyncStr(view, "source") != "shikimori" || view["value"] != title {
		t.Errorf("%q: _view.title = %v, want {value:%q source:shikimori}", rel, view, title)
	}
}

// qaEpAssertStrippedEpisode pins one episode document right after the
// cascade strip: shikimori's namespace, provenance, and view entries are all
// purged while the parser facts survive untouched.
func qaEpAssertStrippedEpisode(t *testing.T, rel string, it itemDTO, season, episode int) {
	t.Helper()
	doc := parseAsyncDoc(t, it.Document)
	if doc.Sources["shikimori"] != nil {
		t.Errorf("%q: sources.shikimori survived the cascade strip: %v", rel, doc.Sources["shikimori"])
	}
	if doc.Provenance["title"] != nil {
		t.Errorf("%q: _provenance.title survived the cascade strip: %v", rel, doc.Provenance["title"])
	}
	if doc.View["title"] != nil {
		t.Errorf("%q: _view.title survived the cascade strip: %v", rel, doc.View["title"])
	}
	qaEpAssertParserFacts(t, rel, doc, season, episode)
}

// qaEpAssertUntouchedEpisode pins one episode document that routing must
// NEVER have touched: no shikimori namespace anywhere, parser facts intact,
// and its row still settled ready (nothing ever stripped it).
func qaEpAssertUntouchedEpisode(t *testing.T, rel string, it itemDTO, season, episode int) {
	t.Helper()
	doc := parseAsyncDoc(t, it.Document)
	if doc.Sources["shikimori"] != nil {
		t.Errorf("%q: sources.shikimori = %v, want absent (another season's episode stays untouched)", rel, doc.Sources["shikimori"])
	}
	if doc.Provenance["title"] != nil || doc.View["title"] != nil {
		t.Errorf("%q: shikimori stamps present (%v / %v), want none", rel, doc.Provenance["title"], doc.View["title"])
	}
	qaEpAssertParserFacts(t, rel, doc, season, episode)
	if it.Status != "ready" {
		t.Errorf("%q: status = %q, want ready (nothing ever stripped or failed it)", rel, it.Status)
	}
}

// qaEpAssertParserFacts pins the serial-parser season/episode facts the
// routing matched on (never disturbed by a routed write, a strip, or a
// re-drain).
func qaEpAssertParserFacts(t *testing.T, rel string, doc asyncDoc, season, episode int) {
	t.Helper()
	ns := doc.Sources["serial-parser"]
	if ns == nil {
		t.Fatalf("%q: sources.serial-parser missing; doc lost its parse namespace", rel)
	}
	if s, e := asyncInt(ns, "season"), asyncInt(ns, "episode"); s != season || e != episode {
		t.Errorf("%q: parser season/episode = %v/%v, want %d/%d", rel, ns["season"], ns["episode"], season, episode)
	}
	if asyncStr(doc.Provenance["season"], "plugin_id") != "serial-parser" {
		t.Errorf("%q: _provenance.season = %v, want the serial-parser write", rel, doc.Provenance["season"])
	}
}

// qaEpAssertSeriesNamespace pins the series namespace identity (RU-first
// title, the fixture facts) and the identifier anchor — re-run after each
// anchored leg, it is the fresh rewrite.
func qaEpAssertSeriesNamespace(t *testing.T, j *qaEpJoint, seriesID string, want qaShikWant) {
	t.Helper()
	sr, status, errCode := qaSerialGetSeries(t, j.w.client, j.w.baseURL, j.w.token, seriesID)
	if status != http.StatusOK {
		t.Fatalf("GET series %s: HTTP %d (%s)", seriesID, status, errCode)
	}
	doc := parseAsyncDoc(t, sr.Document)
	ns, ok := doc.Sources["shikimori"]
	if !ok {
		t.Fatalf("series %s: sources.shikimori missing; doc:\n%s", seriesID, sr.Document)
	}
	title, _ := ns["title"].(map[string]any)
	if asyncStr(title, "romaji") != want.romaji || asyncStr(title, "russian") != want.russian {
		t.Errorf("series %s: sources.shikimori.title = %v, want {romaji:%s russian:%s} (RU-first, anime %d)", seriesID, title, want.romaji, want.russian, want.id)
	}
	if asyncStr(ns, "kind") != "tv" || asyncStr(ns, "status") != "released" {
		t.Errorf("series %s: sources.shikimori kind/status = %q/%q, want tv/released", seriesID, asyncStr(ns, "kind"), asyncStr(ns, "status"))
	}
	if n, _ := ns["episodes"].(float64); int(n) != want.episodes {
		t.Errorf("series %s: sources.shikimori.episodes = %v, want %d", seriesID, ns["episodes"], want.episodes)
	}
	if asyncStr(ns, "aired_on") != want.aired {
		t.Errorf("series %s: sources.shikimori.aired_on = %q, want %q", seriesID, asyncStr(ns, "aired_on"), want.aired)
	}
	if s, _ := ns["score"].(float64); s != want.score {
		t.Errorf("series %s: sources.shikimori.score = %v, want %v (upstream string decoded to a number)", seriesID, ns["score"], want.score)
	}
	if asyncStr(doc.Provenance["title"], "plugin_id") != "shikimori" {
		t.Errorf("series %s: _provenance.title = %v, want a shikimori entry", seriesID, doc.Provenance["title"])
	}
	var raw map[string]any
	if err := json.Unmarshal(sr.Document, &raw); err != nil {
		t.Fatalf("decode series doc: %v", err)
	}
	ids, _ := raw["identifiers"].(map[string]any)
	if got, _ := ids["shikimori_id"].(float64); int(got) != want.id {
		t.Errorf("series %s: identifiers.shikimori_id = %v, want %d (the anchor)", seriesID, ids["shikimori_id"], want.id)
	}
}

// qaEpAssertStrippedSeries pins the series row right after the identify PUT:
// the namespace and its stamps are purged, the parse namespace survives, and
// the anchor already names the picked anime (the strip never touches
// identifiers).
func qaEpAssertStrippedSeries(t *testing.T, j *qaEpJoint, seriesID string, pickedID int) {
	t.Helper()
	sr, status, errCode := qaSerialGetSeries(t, j.w.client, j.w.baseURL, j.w.token, seriesID)
	if status != http.StatusOK {
		t.Fatalf("GET series %s: HTTP %d (%s)", seriesID, status, errCode)
	}
	doc := parseAsyncDoc(t, sr.Document)
	if doc.Sources["shikimori"] != nil {
		t.Errorf("series %s: sources.shikimori survived the strip: %v", seriesID, doc.Sources["shikimori"])
	}
	if doc.Provenance["title"] != nil || doc.View["title"] != nil {
		t.Errorf("series %s: shikimori stamps survived the strip (%v / %v)", seriesID, doc.Provenance["title"], doc.View["title"])
	}
	if doc.Sources["serial-parser"] == nil {
		t.Errorf("series %s: lost its parse namespace to the strip", seriesID)
	}
	var raw map[string]any
	if err := json.Unmarshal(sr.Document, &raw); err != nil {
		t.Fatalf("decode series doc: %v", err)
	}
	ids, _ := raw["identifiers"].(map[string]any)
	if got, _ := ids["shikimori_id"].(float64); int(got) != pickedID {
		t.Errorf("series %s: identifiers.shikimori_id = %v, want %d (the pick; the strip never touches identifiers)", seriesID, ids["shikimori_id"], pickedID)
	}
}

// qaEpAssertAllRequests pins the wire contract on EVERY recorded request:
// GET only, the application UA (never a library default — shikimori.io bans
// those), and consecutive sends spaced at least min_interval apart (the REAL
// gate's contract — the gate serializes the plugin's sends across legs and
// plans alike).
func qaEpAssertAllRequests(t *testing.T, reqs []qaShikReq) {
	t.Helper()
	for i, r := range reqs {
		if r.method != http.MethodGet {
			t.Errorf("request %d: %s %s, want GET", i, r.method, r.path)
		}
		qaShikAssertUA(t, i, r.ua)
		qaShikAssertPacing(t, i, reqs)
	}
}

// qaEpAssertTailPaths pins a leg's request set: exactly the named paths, each
// hit once (order-free — the plan fetches primary-then-extras, but the set is
// the contract).
func qaEpAssertTailPaths(t *testing.T, tail []qaShikReq, wantPaths ...string) {
	t.Helper()
	remaining := make(map[string]int, len(wantPaths))
	for _, p := range wantPaths {
		remaining[p]++
	}
	for i, r := range tail {
		if remaining[r.path] <= 0 {
			t.Errorf("tail request %d hit %s, want exactly one fetch each of %v", i, r.path, wantPaths)
			continue
		}
		remaining[r.path]--
	}
	for p, n := range remaining {
		if n > 0 {
			t.Errorf("tail missed %s (%d fetches short) — the anchored plan must hit every request-plan endpoint", p, n)
		}
	}
}
